#!/usr/bin/env python3
"""
Build Script - Package JRT Tech ANALIST Pro 3.4 into a standalone Windows .exe
Uses PyInstaller to create a distributable Windows application.

IMPORTANT: This script MUST be run on a Windows machine.
PyInstaller cannot cross-compile between macOS and Windows.

Usage (on Windows):
  python build_windows.py
"""

import os
import sys
import subprocess
import shutil

# Monkey patch dis._get_const_info to prevent PyInstaller crash on compiler-generated bytecode anomalies
try:
    import dis
    original_get_const_info = dis._get_const_info
    def new_get_const_info(*args, **kwargs):
        try:
            return original_get_const_info(*args, **kwargs)
        except IndexError:
            const_index = args[0] if args else 0
            return (f"<invalid_const_{const_index}>", repr(f"<invalid_const_{const_index}>"))
    dis._get_const_info = new_get_const_info
except Exception as e:
    print(f"[Build] Warning: failed to patch dis module: {e}")

APP_NAME = "JRT Tech ANALIST Pro"
VERSION = "3.4"

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
MAIN_SCRIPT = os.path.join(SCRIPT_DIR, "AnalistProStudioApp.py")
SERVER_SCRIPT = os.path.join(SCRIPT_DIR, "localhost_server.py")
WEB_DIR = os.path.join(SCRIPT_DIR, "HondaECUTool", "data", "web")
DIST_DIR = os.path.join(SCRIPT_DIR, "dist")
BUILD_DIR = os.path.join(SCRIPT_DIR, "build")

# Icon files (try multiple locations)
ICON_CANDIDATES = [
    os.path.join(SCRIPT_DIR, "icon.ico"),
    os.path.join(SCRIPT_DIR, "HondaECUTool", "data", "web", "favicon.ico"),
]


def check_dependencies():
    """Ensure PyInstaller and other deps are available"""
    deps = {
        "PyInstaller": "pyinstaller",
        "webview": "pywebview",
        "aiohttp": "aiohttp",
        "serial": "pyserial",
    }
    missing = []
    for module_name, pip_name in deps.items():
        try:
            __import__(module_name)
            print(f"  [OK] {pip_name}")
        except ImportError:
            missing.append(pip_name)
            print(f"  [MISSING] {pip_name}")

    if missing:
        print(f"\n[INSTALL] Installing missing dependencies: {', '.join(missing)}")
        subprocess.check_call([sys.executable, "-m", "pip", "install"] + missing)
        print("[INSTALL] Done.\n")


def find_icon():
    """Find the first available icon file."""
    for path in ICON_CANDIDATES:
        if os.path.isfile(path):
            return path
    return None


def collect_data_entries():
    """Build the list of --add-data entries for PyInstaller."""
    sep = ";" if sys.platform == "win32" else ":"
    entries = []

    # 1. Web assets (HTML/CSS/JS/images)
    if os.path.isdir(WEB_DIR):
        entries.append(f"{WEB_DIR}{sep}HondaECUTool/data/web")

    # 2. Server script & seed_key_provider
    if os.path.isfile(SERVER_SCRIPT):
        entries.append(f"{SERVER_SCRIPT}{sep}.")
    seed_key = os.path.join(SCRIPT_DIR, "seed_key_provider.py")
    if os.path.isfile(seed_key):
        entries.append(f"{seed_key}{sep}.")

    # 3. Drivers package (HondaECU, HondaECU_Serial, etc.)
    drivers_dir = os.path.join(SCRIPT_DIR, "drivers")
    if os.path.isdir(drivers_dir):
        entries.append(f"{drivers_dir}{sep}drivers")

    # 4. Protocols package
    protocols_dir = os.path.join(SCRIPT_DIR, "protocols")
    if os.path.isdir(protocols_dir):
        entries.append(f"{protocols_dir}{sep}protocols")

    # 5. Framework package (core, flash, transport, plugins, live_data, database, analyzer, developer)
    framework_dir = os.path.join(SCRIPT_DIR, "framework")
    if os.path.isdir(framework_dir):
        entries.append(f"{framework_dir}{sep}framework")

    # 6. Plugin JSON configs
    plugins_dir = os.path.join(SCRIPT_DIR, "plugins")
    if os.path.isdir(plugins_dir):
        entries.append(f"{plugins_dir}{sep}plugins")

    # 7. Logs directory (create empty one so path exists)
    logs_dir = os.path.join(SCRIPT_DIR, "logs")
    os.makedirs(logs_dir, exist_ok=True)
    # Create a placeholder so PyInstaller includes the directory
    placeholder = os.path.join(logs_dir, ".gitkeep")
    if not os.path.exists(placeholder):
        with open(placeholder, "w") as f:
            f.write("")
    entries.append(f"{logs_dir}{sep}logs")

    return entries


