        "framework.database",
        "framework.database.ecu_database",
        "framework.analyzer",
        "framework.analyzer.packet_decoder",
        "framework.analyzer.protocol_analyzer",
        "framework.analyzer.session_logger",
        "framework.developer",
        "framework.developer.dev_panel",
        # stdlib that PyInstaller may miss
        "hashlib",
        "zlib",
